use base64::{Engine,engine::general_purpose::STANDARD};
use serde::Deserialize;use serde_json::{json,Value};use std::collections::BTreeMap;use sha2::{Digest,Sha256};
use bisect_analysis::{candidate_package::{prepare,Metadata},race_of_candidate::{parse_race_of_candidate_source,RaceParseError}};
#[derive(Deserialize)]#[serde(deny_unknown_fields)]
pub(crate) struct Settings{pub state:String,pub year:String,pub label:String,pub submitter:String,pub timestamp:String}
pub(crate) fn ingest(csv_base64:String,source_name:String,documents:BTreeMap<String,String>,staged_path:String,s:Settings)->Result<Value,String>{
 let safe=|p:&str|!p.is_empty()&&p.len()<=200&&p.bytes().all(|b|b.is_ascii_alphanumeric()||b"_./ -".contains(&b))&&!p.split('/').any(|x|x.is_empty()||[".","..","__proto__","constructor","prototype"].contains(&x));
 if !safe(&source_name)||source_name.contains('/')||!safe(&staged_path)||s.label.is_empty()||s.label.len()>100||!s.label.bytes().all(|b|b.is_ascii_alphanumeric()||b"_-".contains(&b))||["__proto__","constructor","prototype"].contains(&s.label.as_str()){return Err("Supply safe source/document paths and a package label of 1–100 ASCII letters, digits, underscores or hyphens.".into());}
 if s.state.is_empty()||s.state.len()>100||s.year.is_empty()||s.year.len()>20||s.submitter.len()>200||s.timestamp.is_empty()||s.timestamp.len()>100{return Err("Supply bounded state/year/submitter/timestamp labels.".into());}
 if csv_base64.len()>1_398_104||documents.is_empty()||documents.len()>256||documents.values().map(String::len).sum::<usize>()>12*1024*1024{return Err("Select up to 1 MiB annotation CSV and 1–256 documents totaling 8 MiB.".into());}
 let csv=STANDARD.decode(&csv_base64).map_err(|_|"Invalid annotation source base64.")?;if csv.is_empty()||csv.len()>1024*1024{return Err("Annotation CSV must be nonempty and at most 1 MiB.".into());}
 let mut decoded=BTreeMap::new();let mut total=0;for(path,encoded)in documents{if !safe(&path)||path==source_name{return Err("Invalid or colliding document path.".into());}let bytes=STANDARD.decode(encoded).map_err(|_|"Invalid document base64.")?;total+=bytes.len();if total>8*1024*1024{return Err("Documents exceed 8 MiB.".into());}decoded.insert(path,bytes);}
 let staged=decoded.get(&staged_path).ok_or("Select the primary staged attestation document.")?;
 let set=parse_race_of_candidate_source(&csv,&source_name,|p|{let key=p.to_string_lossy().replace('\\',"/");decoded.get(&key).map(|b|format!("{:x}",Sha256::digest(b))).ok_or(RaceParseError::AttestationDocMissing{row:0,path:key})}).map_err(|e|e.to_string())?;
 if set.annotations.len()>2000{return Err("Candidate annotation ingestion supports at most 2,000 rows.".into());}
 let filename=staged_path.rsplit('/').next().unwrap();
 let package=prepare(Metadata{label:s.label,year:s.year,state:s.state,submitter:s.submitter,submitted_at:s.timestamp.clone(),ingested_at:s.timestamp,version:env!("CARGO_PKG_VERSION").into(),build_commit:env!("BISECT_BUILD_COMMIT").into(),rustc_version:env!("BISECT_RUSTC_VERSION").into()},&set,&csv,filename,staged).map_err(|e|e.to_string())?;
 let hashes:BTreeMap<_,_>=decoded.iter().map(|(p,b)|(p.clone(),format!("{:x}",Sha256::digest(b)))).collect();
 Ok(json!({"schema_version":"bisect-candidate-ingest-v1","status":"packaged","manifest":package.manifest,"files":package.files,"staged_path":staged_path,"document_sha256":hashes,"scope":"Shared native candidate-race parser and exact package writer. CSV rows declare curator identity, qualifications, dates, race and independent verification; none is authenticated. Document bytes are hashed without rendering/executing them; format checking uses extensions, not content signatures. Native packaging stages the one explicitly selected attestation under its basename; additional documents referenced by annotations remain external and must be retained separately. Supplied timestamp labels populate native submitted_at and ingested_at. Version/commit/compiler are informational build records. No bloc-voting regression, race-disagreement sensitivity analysis or legal certification occurs. Sources/settings remain inert in saved projects; fresh package export requires Run."}))
}
